 d.portfolio=(Array.isArray(d.portfolio)?d.portfolio:[]).slice(0,4).filter(x=>x&&typeof x==='object').map(x=>({img:String(x.img||'').startsWith('data:image/')?x.img:'',caption:String(x.caption||'').slice(0,60)})).filter(x=>x.img);
