 d.process=(Array.isArray(d.process)?d.process:[]).slice(0,4).map(x=>({icon:String(x.icon||'✦').slice(0,8),title:String(x.title||'').slice(0,60),desc:String(x.desc||'').slice(0,100)}));
 d.faq=(Array.isArray(d.faq)?d.faq:[]).slice(0,4).map(x=>({q:String(x.q||'').slice(0,100),a:String(x.a||'').slice(0,240)}));
 ['target','hoursWeek','opsPct','taxPct','commercialPct','commercialFix','rushPct','discountPct'].forEach(k=>d[k]=finite(d[k],DEF[k]));
 d.target=money(d.target);d.hoursWeek=clamp(d.hoursWeek,1,80);d.opsPct=clamp(d.opsPct,0,80);d.taxPct=clamp(d.taxPct,0,80);d.commercialPct=clamp(d.commercialPct,0,200);d.commercialFix=money(d.commercialFix);d.rushPct=clamp(d.rushPct,0,200);d.discountPct=clamp(d.discountPct,0,100);
 if(!TPL.some(x=>x.id===d.template))d.template='t21';
 const cfg=templates[d.template]||templates.t21;
 d.accent=safeHex(d.accent,cfg.accent||DEF.accent);d.accent2=safeHex(d.accent2,cfg.accent2||DEF.accent2);
