 d.kawaiiDecorations=d.kawaiiDecorations!==false;d.font=FONTS.some(x=>x.id===d.font)?d.font:'';d.density=['compact','normal','spacious'].includes(d.density)?d.density:'normal';d.language=['id','en'].includes(d.language)?d.language:'id';
 ['showQR','watermark','showStats','showPortfolio','showTestimonials','showProcess','showFAQ','showPayment'].forEach(k=>d[k]=!!d[k]);
