function safeRead(){try{const raw=localStorage.getItem(LS)||localStorage.getItem(LEGACY_LS)||'null';return normalizeData(JSON.parse(raw))}catch(e){console.warn('Rate Card: penyimpanan lama tidak bisa dibaca.',e);return cloneDefault()}}
