function calcBaseRate(){const target=money(D.target),ops=clamp(D.opsPct,0,80),tax=clamp(D.taxPct,0,80),hw=Math.max(1,clamp(D.hoursWeek,1,80));const monthlyHours=hw*4.33,denom=Math.max(.05,1-ops/100-tax/100),gross=target/denom;return{monthlyHours,gross,rate:monthlyHours?gross/monthlyHours:0,ops:gross*ops/100,tax:gross*tax/100,net:target,denom}}
function svcQty(s){return clamp(Math.round(number(s.q)||1),1,999)}
function svcTotal(s){return svcQty(s)*money(s.p)}
function sumServices(){return D.services.reduce((sum,s)=>sum+svcTotal(s),0)}
function calcQuote(){const subtotal=sumServices(),commercial=D.commercialFix>0?money(D.commercialFix):Math.round(subtotal*clamp(D.commercialPct,0,200)/100),rush=Math.round(subtotal*clamp(D.rushPct,0,200)/100),discount=Math.round(subtotal*clamp(D.discountPct,0,100)/100);return{subtotal,commercial,rush,discount,total:Math.max(0,subtotal+commercial+rush-discount)}}
function simulateIncome(){return calcQuote().total}
function safePhoto(src){const v=String(src||'').trim();if(/^data:image\/(png|jpe?g|webp|gif);base64,/i.test(v))return v;if(/^https:\/\//i.test(v))return v;return ''}
function getQRPayload(){const custom=String(D.qrPayload||'').trim();if(custom)return custom.slice(0,900);const digits=String(D.wa||'').replace(/\D/g,'');if(digits)return 'https://wa.me/'+(digits[0]==='0'?'62'+digits.slice(1):digits);return String(D.payment||'Mindvesta Payment').slice(0,500)}
function qrDataURL(){const payload=getQRPayload();if(!payload||!window.VFQRCode)return '';if(__qrCache.payload===payload)return __qrCache.url;try{const qr=new window.VFQRCode(0,0);qr.addData(payload);qr.make();const n=qr.getModuleCount(),quiet=4,size=n+quiet*2;let path='';for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(qr.isDark(y,x))path+=`M${x+quiet} ${y+quiet}h1v1h-1z`;const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="#fff"/><path d="${path}" fill="#111"/></svg>`;const url='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);__qrCache={payload,url};return url}catch(e){console.warn('QR lokal gagal dibuat',e);return ''}}
function pickerHTML(){const item=t=>{const c=templates[t.id]||templates.t21,thumb=c.thumb||t.swatch||c.bg,icon=(c.icons&&c.icons[0])||'✦';return `<button type="button" class="tmpl ${D.template===t.id?'on':''}" data-t="${t.id}" data-cat="${t.cat}" aria-pressed="${D.template===t.id}" title="Pilih ${esc(t.n)}"><span class="tmplThumb" style="--swatch:${esc(thumb)};--swatch-accent:${c.accent}" aria-hidden="true"><i></i><em></em><strong>${esc(icon)}</strong></span><span class="tmplMeta"><b><span class="tmplNo">${t.displayOrder||''}.</span> ${esc(t.n)}</b><small><i style="background:${c.accent}"></i><span>${esc(c.accent)}</span></small></span></button>`};const group=(cat,title)=>`<section class="tmplGroup" aria-label="${title}"><h5>${title} <span>${TPL.filter(t=>t.cat===cat).length} tema</span></h5><div class="tmplGroupGrid">${TPL.filter(t=>t.cat===cat).map(item).join('')}</div></section>`;return group('cute','Cute & Kawaii Themes')+group('pro','Professional & Elegant Themes')}
