function applyTemplate(templateId,opts){opts=opts||{};const id=templates[templateId]?templateId:'t21',c=templates[id],oldId=D.template||'t21';if(id!==oldId){if(!D.accentCustom)D.accent=c.accent;if(!D.accent2Custom)D.accent2=c.accent2;D.template=id}else{if(!D.accentCustom&&!D.accent)D.accent=c.accent;if(!D.accent2Custom&&!D.accent2)D.accent2=c.accent2}const doc=$('#rcDoc');if(doc){const utilities=TPL.flatMap(t=>(templates[t.id]?.tailwindClass||'').split(/\s+/).filter(Boolean));if(utilities.length)doc.classList.remove(...utilities);doc.classList.remove(...TPL.map(t=>t.id),...TPL.map(t=>t.cls).filter(Boolean));doc.classList.add('rc',id);const item=TPL.find(t=>t.id===id);if(item?.cls)doc.classList.add(item.cls);(c.tailwindClass||'').split(/\s+/).filter(Boolean).forEach(k=>doc.classList.add(k));const css={'--bg':c.bg,'--card':c.card,'--ink':c.ink,'--mu':c.muted,'--accent-color':D.accent||c.accent,'--accent2-color':D.accent2||c.accent2,'--ac':'var(--accent-color)','--ac2':'var(--accent2-color)','--rad':c.radius,'--shadow':c.shadow,'--font':(FONTS.find(f=>f.id===D.font)?.family||c.font),'--bg-image':c.bgImage||'none','--bg-size':c.bgSize||'auto','--doc-border':c.docBorder||'0','--doc-radius':c.docRadius||c.radius,'--doc-shadow':c.docShadow||'none','--header-bg':c.headerBg||'transparent','--header-color':c.headerColor||c.ink};Object.keys(css).forEach(k=>doc.style.setProperty(k,css[k]));doc.dataset.template=id;doc.dataset.decorations=D.kawaiiDecorations?'on':'off'}if(ov){$$('.tmpl',ov).forEach(b=>{const active=b.dataset.t===id;b.classList.toggle('on',active);b.setAttribute('aria-pressed',active?'true':'false')});const ac=$('[data-f="accent"]',ov),ac2=$('[data-f="accent2"]',ov);if(ac)ac.value=D.accent;if(ac2)ac2.value=D.accent2;const h=$('#rAccentHex',ov),h2=$('#rAccent2Hex',ov);if(h)h.textContent=D.accent;if(h2)h2.textContent=D.accent2}if(opts.save!==false)save();return c}
