function applyQuick(key){const p=QUICK_PRESETS[key];if(!p)return;if(!confirm('Terapkan preset '+p.label+'? Identitas dan daftar layanan saat ini akan diganti.'))return;p.fill(D);save();syncForm();tabTo('data')}
function addSvcPreset(name){const p=SVC_MAP[name]||{emoji:'🎯',d:'',p:0};D.services.push({emoji:p.emoji,n:name,d:p.d,q:1,t:0,p:p.p});save();renderServices();paint()}
function compressImage(file,maxSide,quality){return new Promise((resolve,reject)=>{if(!file||!/^image\//.test(file.type)){reject(new Error('Pilih file gambar.'));return}if(file.size>15*1024*1024){reject(new Error('Ukuran foto maksimal 15 MB sebelum kompresi.'));return}const reader=new FileReader();reader.onerror=()=>reject(new Error('File gambar tidak bisa dibaca.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('Format gambar tidak didukung.'));img.onload=()=>{try{const s=Math.min(1,maxSide/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*s));c.height=Math.max(1,Math.round(img.height*s));const ctx=c.getContext('2d');ctx.drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',quality))}catch(e){reject(e)}};img.src=reader.result};reader.readAsDataURL(file)})}
async function handlePhotoUpload(file){D.photo=await compressImage(file,420,.82);save();syncForm()}
async function handlePortfolioUpload(file){if(D.portfolio.length>=4)throw new Error('Maksimal 4 foto portfolio.');D.portfolio.push({img:await compressImage(file,640,.78),caption:''});save();renderPortfolio();paint()}
function roundRect(ctx,x,y,w,h,r,fill,stroke){const rr=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+rr,y);ctx.arcTo(x+w,y,x+w,y+h,rr);ctx.arcTo(x+w,y+h,x,y+h,rr);ctx.arcTo(x,y+h,x,y,rr);ctx.arcTo(x,y,x+w,y,rr);ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke()}}
function textLines(ctx,text,x,y,maxWidth,lineHeight,font,color,maxLines=3){ctx.font=font;ctx.fillStyle=color;ctx.textAlign='left';const words=String(text||'').split(/\s+/).filter(Boolean);let line='',count=0;for(let i=0;i<words.length;i++){const test=line?line+' '+words[i]:words[i];if(ctx.measureText(test).width>maxWidth&&line){ctx.fillText(line,x,y);y+=lineHeight;count++;line=words[i];if(count>=maxLines-1)break}else line=test}if(line&&count<maxLines){let out=line;while(out.length>2&&ctx.measureText(out+'…').width>maxWidth)out=out.slice(0,-1);ctx.fillText(out+(out!==line?'…':''),x,y);y+=lineHeight}return y}
